import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_kernel_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__device__ float mish_activation(float x) {
    float sp = x > 20.0f ? x : log1pf(expf(x));
    return x * tanhf(sp);
}

__global__ void fused_linear_double_mish_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int in_features,
    int out_features) {

    int global_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (global_idx >= batch_size * out_features) return;

    int row = global_idx / out_features;
    int col = global_idx % out_features;

    float sum = 0.0f;
    for(int k = 0; k < in_features; k++) {
        sum += input[row * in_features + k] * weight[col * in_features + k];
    }
    sum += bias[col];

    // Apply Mish twice
    float first_mish = mish_activation(sum);
    float second_mish = mish_activation(first_mish);

    output[global_idx] = second_mish;
}

torch::Tensor fused_linear_double_mish_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias) {

    auto batch_size = input.size(0);
    auto in_features = input.size(1);
    auto out_features = weight.size(0);

    auto output = torch::zeros({batch_size, out_features}, input.options());

    int num_elements = batch_size * out_features;
    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    fused_linear_double_mish_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_features,
        out_features
    );

    return output;
}
"""

cpp_code = "torch::Tensor fused_linear_double_mish_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias);"

fused_extension = load_inline(
    name='fused_ops',
    cpp_sources=cpp_code,
    cuda_sources=fused_kernel_code,
    functions=['fused_linear_double_mish_cuda'],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features):
        super(ModelNew, self).__init__()
        self.in_features = in_features
        self.out_features = out_features

        self.weight = nn.Parameter(torch.Tensor(out_features, in_features))
        self.bias = nn.Parameter(torch.Tensor(out_features))

        nn.init.kaiming_uniform_(self.weight, a=5**0.5)
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / (fan_in**0.5) if fan_in > 0 else 0
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        return fused_extension.fused_linear_double_mish_cuda(x, self.weight, self.bias)
